-- Instrument register (reference data), loaded from the B3 BVBG.028 file.
-- The id is generated by the application (UUID v7) on first import and never changes afterwards:
-- re-importing updates only the name of existing tickers.
CREATE TABLE IF NOT EXISTS instruments (
    instrument_id UUID PRIMARY KEY,
    ticker TEXT NOT NULL,
    name TEXT NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_instruments_ticker ON instruments(ticker);

-- Daily OHLC history (B3 COTAHIST file), the basis of the simulated quotes engine.
-- Not tied to instruments by foreign key: the history also holds tickers no longer in the register.
CREATE TABLE IF NOT EXISTS quotes (
    ticker TEXT NOT NULL,
    trade_date DATE NOT NULL,
    open_price NUMERIC(13, 2) NOT NULL,
    high_price NUMERIC(13, 2) NOT NULL,
    low_price NUMERIC(13, 2) NOT NULL,
    close_price NUMERIC(13, 2) NOT NULL,
    PRIMARY KEY (ticker, trade_date)
);
